import{_ as r,l as o,o as e,c as s,v as t,p as n,x as i,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"掩模遮挡刀片 REMA","description":"","frontmatter":{"title":"掩模遮挡刀片 REMA","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/reticle-masking-blades.md","filePath":"litho/reticle-masking-blades.md","lastUpdated":1789023840000}'),p={name:"litho/reticle-masking-blades.md"};function m(_,a,E,A,f,u){const l=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="掩模遮挡刀片-rema" tabindex="-1">掩模遮挡刀片 REMA <a class="header-anchor" href="#掩模遮挡刀片-rema" aria-label="Permalink to &quot;掩模遮挡刀片 REMA&quot;">​</a></h1><div class="epigraph"><p>REMA 刀片挡住不该曝光的掩模区：划片槽、邻场、条码。它切的是场，不是光瞳。</p><footer>—— 对照 reticle masking blades 在扫描投影机上的公开功能</footer></div><p><a href="/litho/homogenizer-fly-eye">上一课</a>给出满场均匀照明。缺口是：掩模上并非处处要印。REMA（reticle masking）刀片在掩模附近挡光，定义曝光矩形。与 <a href="/litho/slit-scan-average">狭缝</a> 分工：狭缝是扫描瞬时开口，刀片是这场用哪一块掩模。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>掩模版上有对准标记、邻 die、 Pellicle 边。若整版照明，边缘图形和金属边会印到晶圆或产生杂散。刀片误差直接是场尺寸与边缘剂量梯度。把场边缘 CD 异常全写成镜头畸变，会漏掉刀片半影。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四刀（或等效）围出矩形，随扫描与场尺寸改。半影宽度由刀片离焦与照明 σ 决定，边缘有一段剂量斜坡，小图形不要贴刀片。配方：场大小、刀片余量、是否挡标记。</p>',7)),(e(),n(c,null,{default:i(()=>[h(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20ILL%5B%22%E5%9D%87%E5%85%89%E7%85%A7%E6%98%8E%22%5D%20--%3E%20BL%5B%22REMA%20%E5%88%80%E7%89%87%22%5D%0A%20%20BL%20--%3E%20EXP%5B%22%E6%9B%9D%E5%85%89%E7%9F%A9%E5%BD%A2%22%5D%0A%20%20SLIT%5B%22%E6%89%AB%E6%8F%8F%E7%8B%AD%E7%BC%9D%22%5D%20--%3E%20EXP%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">刀片在物面附近，光瞳整形在照明光瞳。调刀片不会把偶极变成环形；调光瞳不会切场。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>刀片是几何挡光。衍射在刃口产生半影，高 σ 半影更软。扫描方向上狭缝已经限制瞬时场，刀片主要管静态场边界与非扫描边。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课照明均匀性沿狭缝的测量，假定刀片已张开到配方场。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>REMA 切掩模场，狭缝切扫描瞬时开口。</li><li>刃口半影是边缘 CD 源。</li><li>出处：扫描投影机遮挡通识；狭缝课。</li></ul>',7))])}const T=r(p,[["render",m]]);export{k as __pageData,T as default};
